from datetime import date, timedelta
from typing import Dict, Set


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books: Set[str] = set()
        # book_id -> (user, borrow_date)
        self.borrowed: Dict[str, tuple[str, date]] = {}
        # user -> unpaid fine amount
        self.fines: Dict[str, float] = {}

    def add_book(self, book_id: str) -> None:
        self.books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id in self.borrowed:
            raise ValueError(f"Book '{book_id}' is already borrowed.")
        # If the book is not tracked yet, add it automatically
        self.books.add(book_id)
        self.borrowed[book_id] = (user, day)

    def return_book(self, user: str, book_id: str, day: date) -> float:
        """Return a book; returns the fine charged for this return."""
        if book_id not in self.borrowed or self.borrowed[book_id][0] != user:
            raise ValueError(f"User '{user}' has not borrowed book '{book_id}'.")

        borrow_user, borrow_date = self.borrowed.pop(book_id)
        due_date = borrow_date + timedelta(days=self.loan_days)

        fine = 0.0
        if day > due_date:
            # Count overdue days excluding Saturdays and Sundays
            curr = due_date + timedelta(days=1)
            overdue_business_days = 0
            while curr <= day:
                # Monday is 0, Sunday is 6; weekday < 5 means Monday to Friday
                if curr.weekday() < 5:
                    overdue_business_days += 1
                curr += timedelta(days=1)
            fine = overdue_business_days * self.daily_fine

        if fine > 0:
            self.fines[user] = self.fines.get(user, 0.0) + fine

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        """Pay all fines of the user."""
        self.fines[user] = 0.0
